<template>
  <div class="museum-floor-guide" :class="{'is-presentation':presentation,'is-dark':previewTheme==='dark','is-discovering':discovering,'is-overview':overview}" @pointerleave="leavePreview" @focusout="leaveFocus">
    <figure class="plan-drawing">
    <div class="museum-floor-plan" role="group" aria-label="Gallery floor plan">
      <svg class="pavilion-plan" viewBox="-16 -17 42 36" aria-hidden="true">
        <g class="plan-floor"><rect v-for="(floor,index) in floors" :key="index" :x="floor.x" :y="floor.y" :width="floor.width" :height="floor.height" :class="floor.material"/></g>
        <g class="plan-wall"><rect v-for="(wall,index) in walls" :key="index" :x="wall.x" :y="wall.y" :width="wall.width" :height="wall.height"/></g>
        <g class="plan-object" :class="{'is-selected':selected==='directory'}"><rect x="-11.3" y="2.45" width=".5" height="6.5"/></g>
        <g class="plan-object" :class="{'is-selected':selected==='compose'}"><rect x="-7.925" y="-2" width="2.45" height="1.6"/><path d="M-7.6-1.1h1.8m-.9-.6v1.2"/></g>
        <g class="plan-object" :class="{'is-selected':selected==='about'}" transform="translate(6.7 -.6) scale(.85) translate(-6.7 1.2)"><rect x="4.7" y="-3" width="4" height="3.6"/><path d="M5.2-.1v-2.3h2.1v1h1v1.3Z"/></g>
        <g class="plan-object" :class="{'is-selected':selected==='archive'}"><circle cx="16.7" cy="3.4" r="2.45"/><circle cx="16.7" cy="3.4" r="1.73"/><path d="m15.6 3.8.7-1.1 1.5.8-.4 1-1.8-.7Z"/></g>
        <g class="plan-object" :class="{'is-selected':selected==='collection'}"><path d="M-3.7-14h7.4v.6h-7.4Z"/></g>
        <g class="plan-columns"><rect v-for="z in [-9,-3.3,2.35,8]" :key="z" x="-11.61" :y="z-.21" width=".22" height=".42"/><rect x="13.2" y="11.22" width=".2" height=".35"/><rect x="21.7" y="11.22" width=".2" height=".35"/></g>
        <path class="plan-arrival" d="M-1 18h2m-1 0v-3m-.65.65L0 15l.65.65"/>
      </svg>
      <button :disabled="overview" :tabindex="overview ? -1 : undefined" v-for="place in places" :key="place.id" type="button" class="plan-place" :class="{'is-selected':selected===place.id,'is-here':!presentation&&area===place.id,'is-model':place.id==='about'}" :style="regionStyle(place)" :aria-pressed="selected===place.id" :aria-label="`${place.label}${!presentation&&area===place.id?', current location':''}`" @pointerenter="preview(place.id,$event)" @focus="focusPlace(place.id,$event)" @click="select(place.id)">
        <span class="plan-label"><span>{{place.label}}</span><i v-if="!presentation&&area===place.id" aria-hidden="true"></i><svg v-if="presentation" class="plan-place-open" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 12 12 4M4 4h8v8"/></svg></span>
      </button>
      <span v-if="presentation && !overview && showDiscoveryCue" class="plan-discovery-cue" :class="{'is-visible':cueVisible&&!interacted}" aria-hidden="true"><svg viewBox="0 0 20 20"><path d="m4 2 11 9-6 1-2 6Z"/></svg>Explore the Gallery</span>
    </div>
    <figcaption v-if="presentation && !overview" class="plan-caption">The Gallery floor plan</figcaption>
    </figure>
    <section v-if="!overview" class="plan-detail" :aria-live="presentation&&!hovered&&!focused?'off':'polite'" aria-atomic="true">
      <span v-if="!presentation" class="plan-location"><i aria-hidden="true"></i>You are here · {{currentPlace.label}}</span>
      <div class="plan-view" aria-hidden="true">
        <img v-for="place in places" :key="place.id" :src="`/assets/img/gallery-plan/${place.id}-${previewTheme}.webp?v=20260927-2`" :class="{'is-visible':selected===place.id}" alt="" width="800" height="450" decoding="async" draggable="false"/>
      </div>
      <div class="plan-descriptions">
        <div v-for="place in places" :key="place.id" class="plan-description" :class="{'is-visible':selected===place.id}" :aria-hidden="selected!==place.id"><component :is="presentation?'h4':'h3'">{{place.title}}</component><p>{{presentation ? projectDescriptions[place.id] : place.copy}}</p></div>
      </div>
