<script>
import { museumPlanFloors, museumPlanWalls, museumGuidePlaces, museumProjectDescriptions } from '../../utils/museumFloorPlan';
import { initialExhibitionDarkMode } from '../../utils/exhibitionTheme';

// One target includes the object, its label and the surrounding floor space.
const placeRegions = {
  hall: { x:-3, z:5, width:10, height:9.5 },
  directory: { x:-12.3, z:1.8, width:9, height:8.7 },
  collection: { x:-5.6, z:-15.5, width:11.2, height:7.2 },
  compose: { x:-11.5, z:-6.2, width:9.6, height:8.2 },
  archive: { x:12.3, z:-.2, width:9.4, height:10.9 },
  about: { x:.4, z:-7.8, width:11.6, height:9.8 },
};

export default {
  props:{area:{type:String,default:'hall'},presentation:Boolean,overview:Boolean,showDiscoveryCue:{type:Boolean,default:true},dark:{type:Boolean,default:null},followArea:{type:String,default:''},following:Boolean},
  emits:['navigate'],
  data(){return{siteDark:initialExhibitionDarkMode(),interacted:false,cueVisible:false,discovering:false,inViewport:false,hovered:'',focused:'',selected:museumGuidePlaces.some(place=>place.id===this.area)?this.area:'hall',places:museumGuidePlaces,projectDescriptions:museumProjectDescriptions,floors:museumPlanFloors,walls:museumPlanWalls};},
  watch:{followArea(){this.followScene();},following(){this.followScene();}},
  mounted(){
    this.syncTheme();window.addEventListener('theme-change',this.syncTheme);
    if(this.presentation){
      this._discoveryObserver=new IntersectionObserver(([entry])=>{
        this.inViewport=entry.isIntersecting&&entry.intersectionRatio>=.25;
        if(!this.inViewport){this.stopDiscovery();return;}
        this.followScene();
        if(this.interacted||this._demonstrated)return;
        this.cueVisible=true;
        if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
        clearTimeout(this._discoveryTimer);
        this._discoveryTimer=setTimeout(()=>{
          if(this.interacted)return;
          this._demonstrated=true;this.discovering=true;
          this._discoveryTimer=setTimeout(()=>{this.discovering=false;},1700);
        },650);
      },{threshold:[0,.25]});
      this._discoveryObserver.observe(this.$el);
    }
  },
  beforeUnmount(){window.removeEventListener('theme-change',this.syncTheme);this.stopDiscovery();this._discoveryObserver?.disconnect();},
  computed:{previewTheme(){return (this.dark??this.siteDark)?'dark':'light';},activePlace(){return this.places.find(place=>place.id===this.selected);},currentPlace(){return this.places.find(place=>place.id===this.area)||this.places[0];}},
  methods:{
    syncTheme(){this.siteDark=initialExhibitionDarkMode();},
    stopDiscovery(){clearTimeout(this._discoveryTimer);this.discovering=false;},
    select(id){this.interacted=true;this.stopDiscovery();this.selected=id;},
    preview(id,event){if(event.pointerType==='mouse'){this.hovered=id;this.select(id);}},
    focusPlace(id,event){if(event.target.matches(':focus-visible')||window.matchMedia('(hover: none)').matches){this.focused=id;this.select(id);}},
    leavePreview(){this.hovered='';this.followScene();},
    leaveFocus(event){if(!this.$el.contains(event.relatedTarget)){this.focused='';this.followScene();}},
    followScene(){if(this.presentation&&this.following&&this.inViewport&&!this.hovered&&!this.focused&&this.places.some(place=>place.id===this.followArea))this.selected=this.followArea;},
    regionStyle(place){
      const region=placeRegions[place.id];
      return {
        left:`${(region.x+16)/42*100}%`,top:`${(region.z+17)/36*100}%`,
        width:`${region.width/42*100}%`,height:`${region.height/36*100}%`,
        '--label-x':`${(place.x-region.x)/region.width*100}%`,
        '--label-y':`${(place.z-region.z)/region.height*100}%`,
      };
    },
  },
};
</script>
